insert into talent_versions (code, name) values ('myself-v1', 'Know Yourself (public, pre-programme)')
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='myself-v1'), 'A', '{"en": "How You Work", "ms-MY": "Cara Anda Bekerja", "id-ID": "Cara Anda Bekerja"}'::jsonb, '{"en": "How you naturally work day to day. No answer is better than another.", "ms-MY": "Cara anda bekerja dari hari ke hari. Tiada jawapan yang lebih baik daripada yang lain.", "id-ID": "Cara Anda bekerja sehari-hari. Tidak ada jawaban yang lebih baik dari yang lain."}'::jsonb, 0);
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='myself-v1'), 'B', '{"en": "Drive and Follow-Through", "ms-MY": "Dorongan dan Ketekunan", "id-ID": "Dorongan dan Ketekunan"}'::jsonb, '{"en": "How you keep going when nobody is watching.", "ms-MY": "Bagaimana anda meneruskan usaha apabila tiada siapa memerhati.", "id-ID": "Bagaimana Anda tetap berjalan saat tidak ada yang mengawasi."}'::jsonb, 1);
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='myself-v1'), 'C', '{"en": "Ownership and Risk", "ms-MY": "Tanggungjawab dan Risiko", "id-ID": "Tanggung Jawab dan Risiko"}'::jsonb, '{"en": "How you handle responsibility, uncertainty and reward.", "ms-MY": "Cara anda mengendalikan tanggungjawab, ketidakpastian dan ganjaran.", "id-ID": "Cara Anda menangani tanggung jawab, ketidakpastian, dan imbalan."}'::jsonb, 2);
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='myself-v1'), 'D', '{"en": "What Moves You", "ms-MY": "Apa yang Menggerakkan Anda", "id-ID": "Apa yang Menggerakkan Anda"}'::jsonb, '{"en": "What you are actually chasing, in your own terms.", "ms-MY": "Apa yang anda kejar sebenarnya, mengikut takrifan anda sendiri.", "id-ID": "Apa yang sebenarnya Anda kejar, menurut definisi Anda sendiri."}'::jsonb, 3);
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='myself-v1'), 'E', '{"en": "What Would Wear You Down", "ms-MY": "Apa yang Melemahkan Anda", "id-ID": "Apa yang Melemahkan Anda"}'::jsonb, '{"en": "Being honest here helps more than looking strong.", "ms-MY": "Berterus terang di sini lebih membantu daripada cuba nampak kuat.", "id-ID": "Jujur di sini lebih membantu daripada terlihat kuat."}'::jsonb, 4);
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='myself-v1'), 'F', '{"en": "Real Situations", "ms-MY": "Situasi Sebenar", "id-ID": "Situasi Nyata"}'::jsonb, '{"en": "Every option is a reasonable thing to do. Choose what you would actually do.", "ms-MY": "Setiap pilihan adalah tindakan yang munasabah. Pilih apa yang anda benar-benar akan buat.", "id-ID": "Setiap pilihan adalah tindakan yang masuk akal. Pilih apa yang benar-benar akan Anda lakukan."}'::jsonb, 5);
insert into talent_sections (version_id, code, title, intro, sort_order) values ((select id from talent_versions where code='myself-v1'), 'G', '{"en": "In Your Own Words", "ms-MY": "Dengan Perkataan Anda Sendiri", "id-ID": "Dengan Kata-Kata Anda Sendiri"}'::jsonb, '{"en": "Short answers are fine. There are no right answers.", "ms-MY": "Jawapan ringkas sudah memadai. Tiada jawapan yang betul atau salah.", "id-ID": "Jawaban singkat sudah cukup. Tidak ada jawaban benar atau salah."}'::jsonb, 6);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='A'), 'A1', 'frequency', '{"en": "In the last 30 days, how often did you start a conversation with someone you did not know well?", "ms-MY": "Dalam 30 hari lepas, berapa kerap anda memulakan perbualan dengan seseorang yang anda tidak kenali rapat?", "id-ID": "Dalam 30 hari terakhir, seberapa sering Anda memulai percakapan dengan orang yang belum Anda kenal dekat?"}'::jsonb, null, 'style.social_energy', false, false, true, null, 0);
