insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='F'), 'F1', 'scenario', '{"en": "You are two months in and have not closed anything yet. What do you actually do next?", "ms-MY": "Anda sudah dua bulan dan belum menutup sebarang jualan. Apa yang anda buat seterusnya?", "id-ID": "Anda sudah dua bulan dan belum menutup satu pun penjualan. Apa yang Anda lakukan selanjutnya?"}'::jsonb, null, 'role', false, true, true, null, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F1'), 1, '{"en": "Go back to basics and increase the number of people I speak to each day", "ms-MY": "Kembali kepada asas dan tambah bilangan orang yang saya hubungi setiap hari", "id-ID": "Kembali ke dasar dan menambah jumlah orang yang saya hubungi setiap hari"}'::jsonb, '{"role.prospector": 2, "success.consistency": 1}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F1'), 2, '{"en": "Ask someone experienced to watch me work and tell me what I am doing wrong", "ms-MY": "Minta seseorang yang berpengalaman melihat saya bekerja dan beritahu kesilapan saya", "id-ID": "Meminta orang berpengalaman mengamati cara saya bekerja dan memberi tahu kesalahan saya"}'::jsonb, '{"success.coachability": 2, "role.coach_trainer": 0.5}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F1'), 3, '{"en": "Study the area and the pricing until I can answer any question about it", "ms-MY": "Kaji kawasan dan harga sehingga saya boleh jawab apa-apa soalan mengenainya", "id-ID": "Mempelajari area dan harga sampai saya bisa menjawab pertanyaan apa pun tentangnya"}'::jsonb, '{"style.detail": 2, "role.presenter": 0.8}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F1'), 4, '{"en": "Build an online presence so people start coming to me", "ms-MY": "Bina kehadiran dalam talian supaya orang mula datang kepada saya", "id-ID": "Membangun kehadiran online agar orang mulai datang kepada saya"}'::jsonb, '{"role.content_creator": 2, "style.visibility": 1}'::jsonb, 3);
