insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F2'), 1, '{"en": "Keep in touch lightly and regularly, without pushing", "ms-MY": "Kekal berhubung secara ringan dan tetap, tanpa mendesak", "id-ID": "Tetap berhubungan secara ringan dan teratur, tanpa mendesak"}'::jsonb, '{"role.relationship_builder": 2, "ent.persistence": 1}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F2'), 2, '{"en": "Call once and ask directly what is holding them back", "ms-MY": "Telefon sekali dan tanya terus apa yang menghalang mereka", "id-ID": "Menelepon sekali dan bertanya langsung apa yang menahan mereka"}'::jsonb, '{"role.closer": 2, "style.decision_speed": 1}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F2'), 3, '{"en": "Send them something useful and let them come back on their own", "ms-MY": "Hantar sesuatu yang berguna dan biar mereka kembali sendiri", "id-ID": "Mengirimkan sesuatu yang berguna dan membiarkan mereka kembali sendiri"}'::jsonb, '{"role.content_creator": 1.5, "style.autonomy": 0.5}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F2'), 4, '{"en": "Move my energy to new people and keep this one warm in the background", "ms-MY": "Alihkan tenaga saya kepada orang baharu dan kekalkan yang ini secara sampingan", "id-ID": "Mengalihkan energi ke orang baru dan menjaga yang ini tetap hangat di belakang"}'::jsonb, '{"role.prospector": 2, "success.goal_focus": 0.8}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='F'), 'F3', 'scenario', '{"en": "You have three free hours on a weekday and nobody has told you what to do. How do you spend them?", "ms-MY": "Anda ada tiga jam lapang pada hari bekerja dan tiada siapa beritahu apa nak buat. Bagaimana anda gunakannya?", "id-ID": "Anda punya tiga jam kosong di hari kerja dan tidak ada yang menyuruh apa pun. Bagaimana Anda memakainya?"}'::jsonb, null, 'role', false, true, true, null, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F3'), 1, '{"en": "Contact people I have not spoken to in a while", "ms-MY": "Hubungi orang yang saya sudah lama tidak bercakap dengannya", "id-ID": "Menghubungi orang-orang yang sudah lama tidak saya ajak bicara"}'::jsonb, '{"role.prospector": 1.5, "role.relationship_builder": 1}'::jsonb, 0);
