insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F3'), 3, '{"en": "Learn the product and paperwork properly", "ms-MY": "Pelajari produk dan dokumentasi dengan betul", "id-ID": "Mempelajari produk dan dokumen dengan benar"}'::jsonb, '{"style.detail": 1.5, "role.financing_coordinator": 1}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F3'), 4, '{"en": "Tidy my own records so I know exactly where everything stands", "ms-MY": "Kemas rekod saya sendiri supaya saya tahu kedudukan setiap perkara", "id-ID": "Merapikan catatan saya sendiri agar saya tahu persis posisi setiap hal"}'::jsonb, '{"success.self_management": 2, "style.planning": 1}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='F'), 'F4', 'scenario', '{"en": "A buyer you are helping looks likely to be rejected for their loan. What is your instinct?", "ms-MY": "Seorang pembeli yang anda bantu nampak berkemungkinan ditolak pinjamannya. Apa gerak hati anda?", "id-ID": "Seorang pembeli yang Anda bantu tampaknya akan ditolak pinjamannya. Apa naluri Anda?"}'::jsonb, null, 'role', false, true, true, null, 3);
