insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F4'), 3, '{"en": "Look for a different property that fits what they can actually get", "ms-MY": "Cari hartanah lain yang sesuai dengan apa yang mereka mampu dapat", "id-ID": "Mencari properti lain yang sesuai dengan yang benar-benar bisa mereka dapatkan"}'::jsonb, '{"ent.resourcefulness": 2, "role.closer": 0.8}'::jsonb, 2);
