insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='F'), 'F5', 'scenario', '{"en": "You are asked to present to twenty people you have never met, next week. How do you feel about it?", "ms-MY": "Anda diminta membentangkan kepada dua puluh orang yang anda tidak pernah temui, minggu depan. Bagaimana perasaan anda?", "id-ID": "Anda diminta presentasi di depan dua puluh orang yang belum pernah Anda temui, minggu depan. Bagaimana perasaan Anda?"}'::jsonb, null, 'role', false, true, true, null, 4);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F5'), 1, '{"en": "Good — I am at my best in front of a room", "ms-MY": "Bagus — saya paling bagus di hadapan orang ramai", "id-ID": "Bagus — saya paling maksimal di depan banyak orang"}'::jsonb, '{"role.presenter": 2, "style.visibility": 1}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F5'), 2, '{"en": "Fine, as long as I can prepare properly first", "ms-MY": "Boleh, asalkan saya boleh bersedia dengan betul dahulu", "id-ID": "Tidak masalah, asalkan saya bisa mempersiapkan diri dengan baik dulu"}'::jsonb, '{"style.planning": 2, "role.presenter": 0.8}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F5'), 3, '{"en": "I would rather talk to them one at a time", "ms-MY": "Saya lebih suka bercakap dengan mereka seorang demi seorang", "id-ID": "Saya lebih suka berbicara dengan mereka satu per satu"}'::jsonb, '{"role.relationship_builder": 2, "style.autonomy": 0.5}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F5'), 4, '{"en": "I would do it, but it would cost me a lot of energy", "ms-MY": "Saya akan lakukannya, tetapi ia memerlukan tenaga yang banyak", "id-ID": "Saya akan melakukannya, tetapi itu menguras banyak energi saya"}'::jsonb, '{"success.resilience": 1.5, "demotivator.public_pressure": 1}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='F'), 'F6', 'scenario', '{"en": "Someone newer than you asks you to teach them what you have learned. What happens?", "ms-MY": "Seseorang yang lebih baharu daripada anda minta anda mengajar apa yang anda telah pelajari. Apa yang berlaku?", "id-ID": "Seseorang yang lebih baru dari Anda meminta diajari apa yang sudah Anda pelajari. Apa yang terjadi?"}'::jsonb, null, 'role', false, true, true, null, 5);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F6'), 1, '{"en": "I sit with them and walk through it properly", "ms-MY": "Saya duduk bersama mereka dan terangkan dengan betul", "id-ID": "Saya duduk bersama mereka dan menjelaskannya dengan benar"}'::jsonb, '{"role.coach_trainer": 2, "motivation.helping_others": 1}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F6'), 2, '{"en": "I bring them along and let them watch me work", "ms-MY": "Saya bawa mereka bersama dan biar mereka lihat saya bekerja", "id-ID": "Saya mengajak mereka dan membiarkan mereka melihat saya bekerja"}'::jsonb, '{"role.leader": 1.5, "role.coach_trainer": 1}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F6'), 3, '{"en": "I share what I have and get back to my own targets", "ms-MY": "Saya kongsi apa yang ada dan kembali kepada sasaran saya sendiri", "id-ID": "Saya membagikan yang saya punya lalu kembali ke target saya sendiri"}'::jsonb, '{"success.goal_focus": 1.5, "style.autonomy": 1}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F6'), 4, '{"en": "I would want more people like them around me", "ms-MY": "Saya mahu lebih ramai orang seperti mereka di sekeliling saya", "id-ID": "Saya ingin lebih banyak orang seperti mereka di sekitar saya"}'::jsonb, '{"role.recruiter": 2, "motivation.leadership_influence": 1}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='G'), 'G1', 'text', '{"en": "Why are you looking at real estate now, at this point in your life?", "ms-MY": "Mengapa anda melihat bidang hartanah sekarang, pada waktu ini dalam hidup anda?", "id-ID": "Mengapa Anda melirik properti sekarang, di titik ini dalam hidup Anda?"}'::jsonb, null, 'reflection', false, false, false, 1500, 0);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='G'), 'G2', 'text', '{"en": "What are you willing to do consistently for the next 12 months to make it work?", "ms-MY": "Apakah yang anda sanggup lakukan secara konsisten dalam 12 bulan akan datang untuk menjayakannya?", "id-ID": "Apa yang bersedia Anda lakukan secara konsisten dalam 12 bulan ke depan agar berhasil?"}'::jsonb, null, 'reflection', false, false, false, 1500, 1);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='G'), 'G3', 'text', '{"en": "What usually causes you to stop, delay, or lose confidence?", "ms-MY": "Apakah yang biasanya menyebabkan anda berhenti, bertangguh atau hilang keyakinan?", "id-ID": "Apa yang biasanya membuat Anda berhenti, menunda, atau kehilangan kepercayaan diri?"}'::jsonb, null, 'reflection', false, false, false, 1500, 2);
